INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-oud-mubakhar', 'oud-mubakhar', 'Oud Mubakhar', 'Oud', 'Pure oud oil, aged six years', 'Hydro-distilled from wild-harvested agarwood heartwood and matured for six years in small glass demijohns. It opens with warm resinous smoke before settling into honeyed leather and quiet wood that lingers on skin and linen until the next day.', '{"top":"Warm kinam bark, toasted cardamom husk, dry saffron thread","heart":"Aged Assam agarwood resin, smoked honeycomb, dark fig leaf","base":"Six-year cured heartwood, Mysore sandalwood, warm skin musk"}'::jsonb, NULL, 'Draw the glass dipstick lightly across the inside of each wrist and behind the earlobes. Do not rub the wrists together; let body heat unfold the resin slowly.', true, 4) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
