INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-oud-malaki', 'oud-malaki', 'Oud Malaki', 'Oud', 'Oud and Taif rose oil', 'A classic dialogue between dark Cambodi oud oil and first-flush Rosa damascena distilled in the highlands of Taif. Dewy crimson petals lift the deep wood into a luminous, velvety composition of remarkable poise.', '{"top":"First-harvest Taif rose Otto, pink peppercorn, crushed bergamot peel","heart":"Aged Cambodi agarwood, red geranium leaf, saffron stamen","base":"Smoked cedarwood, labdanum resin, dark ambergris accord"}'::jsonb, NULL, 'Touch a single drop to pulse points at the wrist and collarbone. Particularly resonant in cool evening air or layered beneath Nuit d’Oud.', true, 5) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
