INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-nuit-doud', 'nuit-doud', 'Nuit d’Oud', 'Perfume', 'Eau de parfum, woody', 'Composed for Lagos and Abuja evenings when the heat softens into dusk. Smoked agarwood, roasted cocoa shell and dry atlas cedar unfold over a warm base of Nigerian frankincense and vetiver root.', '{"top":"Black cardamom, calabrian bergamot, roasted Nigerian cocoa shell","heart":"Smoked agarwood heart, Somalian frankincense tears, iris butter","base":"Haitian vetiver root, Atlas cedarwood, dark benzoin resin"}'::jsonb, NULL, 'Mist once or twice onto bare skin from twenty centimetres away. For deeper longevity, layer over a drop of Huile Précieuse.', true, 6) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
