INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-velours-blanc', 'velours-blanc', 'Velours Blanc', 'Perfume', 'Eau de parfum, musk', 'An intimate skin scent built around white ambrette seed, steamed rice vapour and sun-warmed cotton. It sits close to the wearer—clean, lactonic and quietly addictive from morning until night.', '{"top":"Botanical ambrette seed, white tea leaf, crisp pear skin","heart":"Florentine orris root, steamed basmati accord, white magnolia petal","base":"Cashmere wood, clean skin musk, Madagascar vanilla bean"}'::jsonb, NULL, 'Mist onto pulse points and the inside of your collar. Designed for everyday wear when you want your scent noticed only by those invited close.', true, 7) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
