INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-musc-soie', 'musc-soie', 'Musc Soie', 'Roll-ons', 'Perfume oil roll-on', 'A translucent botanical musk woven with white iris, almond milk and clean linen. Alcohol-free and gentle on sensitive skin, it wraps the wearer in a calm, second-skin softness.', '{"top":"Sweet almond milk, white bergamot, cotton flower","heart":"Pallida iris butter, heliotrope blossom, lily of the valley","base":"Silk musk accord, white cedar, Nigerian baobab carrier oil"}'::jsonb, NULL, 'Apply directly to pulse points after bathing while skin is still warm and slightly damp.', true, 10) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
