INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-oud-et-santal', 'oud-et-santal', 'Oud & Santal', 'Oils', 'Hair and body oil', 'Cold-pressed Nigerian moringa and baobab oils infused with aged sandalwood and a trace of smoked oud resin. Formulated to seal moisture into braided, locs or natural textured hair and leave the shoulders softly perfumed.', '{"top":"Cardamom pod, warm Elemi resin","heart":"Mysore sandalwood heart, roasted moringa seed","base":"Smoked agarwood infusion, Madagascar vanilla pod, Peru balsam"}'::jsonb, '["Cold-pressed Nigerian Moringa oleifera seed oil","Unrefined Adansonia digitata (baobab) oil and jojoba esters","Santalum album (sandalwood) and Aquilaria agallocha (oud) infusion","Rosemary leaf antioxidant extract"]'::jsonb, 'Warm three to five drops between palms and smooth through hair lengths, scalp or across the collarbones and arms.', true, 12) ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, category = EXCLUDED.category, type = EXCLUDED.type, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use, is_published = EXCLUDED.is_published, sort_order = EXCLUDED.sort_order;
